// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address baseToken_, address nft_, uint128 vBase, uint128 vNft, uint56 changeFee_, uint16 feeRate_, bytes32 merkleRoot_, bool useOracle, bool payRoyalties) public {
        vm.assume(feeRate_ <= 6000);

        bool ok;
        try c.initialize(baseToken_, nft_, vBase, vNft, changeFee_, feeRate_, merkleRoot_, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!ok) return;

        assertTrue(c.nft() == nft_);
    }
}
